// Se junta la respuesta del agente con el resultado del guardado,
// para que quien pregunto sepa si quedo registrado y cuando.
const guardado = $input.first().json || {};
const agente = $('Preguntar al agente').first().json || {};
return [{ json: {
  respuesta: agente.respuesta || '',
  session_id: agente.session_id || 'default',
  turnos_en_memoria: agente.turnos_en_memoria || 0,
  modo: agente.modo || '',
  memoria_guardada: guardado.guardado === true,
  memoria_coleccion: guardado.coleccion || '',
  memoria_fecha: guardado.fecha || '',
  memoria_motivo: guardado.motivo || '',
  memoria_en_indice: guardado.en_indice === true,
  memoria_en_espera: guardado.guardado === true && guardado.en_indice !== true,
  orquestado_por: 'n8n',
  ejecucion_id: String($execution.id),
  timestamp: new Date().toISOString()
}}];
